INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q25043404', 'November 1966 Burundian coup d''état', 'On 28 November 1966, Michel Micombero, Burundi''s 26-year-old Prime Minister, ousted the 19-year-old king (mwami) of Burundi, Ntare V, in a coup d''état. Ntare was out of the country at the time and the coup leaders quickly succeeded in taking control.', 1966, 11, 29, NULL, NULL, NULL, 'day', '29 November 1966', 39, 'https://en.wikipedia.org/wiki/November_1966_Burundian_coup_d''%C3%A9tat'),
  ('Q25043458', 'July 1966 Burundian coup d''état', 'On 8 July 1966, a coup d''état took place in the Kingdom of Burundi. The second in Burundi''s post-independence history, the coup ousted the government loyal to the king (mwami) of Burundi, Mwambutsa IV, who had gone into exile in October 1965 after the failure of an earlier coup attempt.', 1966, 7, 8, NULL, NULL, NULL, 'day', '8 July 1966', 39, 'https://en.wikipedia.org/wiki/July_1966_Burundian_coup_d''%C3%A9tat'),
  ('Q65067658', '1972 Genocide of Burundian Hutus', 'The Ikiza (variously translated from Kirundi as the Catastrophe, the Great Calamity, and the Scourge), or the Ubwicanyi (Killings), was a series of mass killings—often characterised as a genocide—which were committed in Burundi in 1972 by the Tutsi-dominated army and government, primarily against educated and elite Hutus who lived in the country. Conservative estimates place the death toll of the event between 100,000 and 150,000 killed, while some estimates of the death toll go as high as 300,000.', 1972, 4, NULL, 1972, 8, NULL, 'month', 'April 1972 – August 1972', 41, 'https://en.wikipedia.org/wiki/Ikiza'),
  ('Q23038154', '1976 Burundian coup d''état', 'The 1976 Burundian coup d''état was a bloodless military coup that took place in Burundi on 1 November 1976. An Army faction, led by Deputy Chief of Staff Jean-Baptiste Bagaza, ousted President Michel Micombero.', 1976, 11, 1, NULL, NULL, NULL, 'day', '1 November 1976', 34, 'https://en.wikipedia.org/wiki/1976_Burundian_coup_d''%C3%A9tat'),
  ('Q4583594', '1987 Burundian coup d''état', 'The 1987 Burundian coup d''état was a bloodless military coup that took place in Burundi on 3 September 1987. Tutsi president Jean-Baptiste Bagaza was deposed whilst traveling abroad and succeeded by Tutsi Major Pierre Buyoya.', 1987, 9, 3, NULL, NULL, NULL, 'day', '3 September 1987', 39, 'https://en.wikipedia.org/wiki/1987_Burundian_coup_d''%C3%A9tat'),
  ('Q647239', 'Burundi Civil War', 'The Burundian Civil War was a civil war in Burundi lasting from 1993 to 2005. The civil war was the result of longstanding ethnic divisions between the Hutu and the Tutsi ethnic groups.', 1993, 10, 21, 2005, 5, 15, 'day', '21 October 1993 – 15 May 2005', 61, 'https://en.wikipedia.org/wiki/Burundian_Civil_War'),
  ('Q838695', 'First Congo War', 'The First Congo War, also known as Africa''s First World War, was a civil and international military conflict that lasted from 24 October 1996 to 16 May 1997, primarily taking place in Zaire (which was renamed the Democratic Republic of the Congo during the conflict). The war resulted in the overthrow of Zairean President Mobutu Sese Seko, who was replaced by rebel leader Laurent-Désiré Kabila.', 1996, 10, 24, 1997, 5, 16, 'day', '24 October 1996 – 16 May 1997', 72, 'https://en.wikipedia.org/wiki/First_Congo_War'),
  ('Q4591257', '1996 Burundian coup d''état', 'The 1996 Burundian coup d''état was a military coup d''état that took place in Burundi on 25 July 1996. In the midst of the Burundi Civil War, former president Pierre Buyoya (a Tutsi) deposed Hutu President Sylvestre Ntibantunganya.', 1996, 7, 25, NULL, NULL, NULL, 'day', '25 July 1996', 37, 'https://en.wikipedia.org/wiki/1996_Burundian_coup_d''%C3%A9tat'),
  ('Q75756', 'Second Congo War', 'The Second Congo War, also known as Africa''s World War or the Great War of Africa, was a major conflict that began on 2 August 1998 in the Democratic Republic of the Congo (DRC), just over a year after the First Congo War. The war initially erupted when Congolese president Laurent-Désiré Kabila turned against his former allies from Rwanda and Uganda, who had helped him seize power.', 1998, 8, 2, 2003, 6, 30, 'day', '2 August 1998 – 30 June 2003', 75, 'https://en.wikipedia.org/wiki/Second_Congo_War');

